function Get-Greeting {
 [CmdletBinding(SupportsShouldProcess=$true)]
 param([Parameter(Mandatory,Position=0)][ValidateNotNullOrEmpty()][string]$Name, [switch]$Loud)
 begin { $prefix = "Hello" }
 process { "$prefix $Name" }
 end { "done" }
 clean { "cleanup" }
}

class Person {
 [string]$Name
 hidden [int]$Age = 0
 static [int]$Count = 0
 Person([string]$name) { $this.Name = $name }
 [string] ToString() { return $this.Name }
 static [Person] Create([string]$name) { return [Person]::new($name) }
}

function Read-Config {
 [CmdletBinding()] param([Parameter(Mandatory)][string]$Path)
 try { Get-Content -LiteralPath $Path -Raw -ErrorAction Stop | ConvertFrom-Json }
 catch { throw "Could not read ${Path}: $($_.Exception.Message)" }
}

