function Remove-Example {
    [CmdletBinding(SupportsShouldProcess, ConfirmImpact='High', DefaultParameterSetName='Path')]
    param(
        [Parameter(Mandatory, ValueFromPipeline, ParameterSetName='Path')]
        [ValidateNotNullOrEmpty()]
        [string[]] $Path,
        [Parameter(Mandatory, ParameterSetName='Id')]
        [guid] $Id,
        [switch] $Force
    )
    begin { $removed = 0 }
    process {
        foreach ($item in $Path) {
            if ($PSCmdlet.ShouldProcess($item, 'Remove example')) {
                Remove-Item -LiteralPath $item -Force:$Force -ErrorAction Stop
                $removed++
            }
        }
    }
    end { Write-Verbose ("Removed {0} items" -f $removed) }
    clean { Write-Debug 'cleanup' }
}

function ConvertTo-ExampleRecord {
    [CmdletBinding()]
    [OutputType([pscustomobject])]
    param(
        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [Alias('FullName')]
        [string] $Path,
        [ValidateSet('Small', 'Large')]
        [string] $Size = 'Small'
    )
    process {
        $file = Get-Item -LiteralPath $Path
        [pscustomobject]@{
            Name = $file.Name
            Path = $file.FullName
            Bytes = $file.Length
            Size = $Size
            Modified = $file.LastWriteTimeUtc.ToString('o')
        }
    }
}
Get-ChildItem . -File | ConvertTo-ExampleRecord -Size Large

[CmdletBinding()]
param([uri] $Endpoint, [securestring] $Token)
$request = @{
    Uri = [uri]::new($Endpoint, 'api/items')
    Method = 'Post'
    Authentication = 'Bearer'
    Token = $Token
    ContentType = 'application/json'
    Body = @{ Name = 'example'; Values = @(1, 2, 3) } | ConvertTo-Json -Depth 5
    ErrorAction = 'Stop'
}
try {
    $response = Invoke-RestMethod @request
    $response.items | Where-Object { $_.enabled } | Select-Object id, name
} catch {
    Write-Error -ErrorRecord $_
    throw
}

param([string] $Executable = 'example', [string] $Path = '.')
$arguments = @(
    '--input'
    (Resolve-Path -LiteralPath $Path).Path
    '--label'
    "user:${env:USER}"
    '--format=json'
)
& $Executable @arguments 2>&1 | ForEach-Object { Write-Verbose "native: $_" }
if ($LASTEXITCODE -ne 0) {
    throw "Native command failed with exit code $LASTEXITCODE"
}

function ConvertTo-Port {
    param([Parameter(Mandatory)][string] $Text)
    [int] $value = 0
    if (-not [int]::TryParse($Text, [ref] $value)) {
        throw [ArgumentException]::new("Invalid port: $Text")
    }
    if ($value -notin 1..65535) { throw 'Port is out of range' }
    return $value
}

param([string] $Root = '.', [string] $Algorithm = 'SHA256')
Get-ChildItem -LiteralPath $Root -File -Recurse |
    ForEach-Object -Parallel {
        $hash = Get-FileHash -LiteralPath $_.FullName -Algorithm $using:Algorithm
        [pscustomobject]@{ Path = $_.FullName; Hash = $hash.Hash }
    } -ThrottleLimit 4 |
    Sort-Object Path

BeforeAll { . "$PSScriptRoot/Example.ps1" }
Describe 'ConvertTo-Port' {
    It 'converts a valid port' {
        ConvertTo-Port '443' | Should -Be 443
    }
    It 'rejects invalid text' {
        { ConvertTo-Port 'nope' } | Should -Throw
    }
    It 'accepts <Value>' -TestCases @(@{ Value = '80' }, @{ Value = '443' }) {
        param($Value)
        ConvertTo-Port $Value | Should -BeGreaterThan 0
    }
}

using namespace System.Collections.Generic
class Buffer : System.IDisposable {
    hidden [List[string]] $Items = [List[string]]::new()
    [bool] $Disposed = $false
    Buffer([string[]] $values) { $this.Items.AddRange($values) }
    [void] Add([string] $value) {
        if ($this.Disposed) { throw [ObjectDisposedException]::new('Buffer') }
        $this.Items.Add($value)
    }
    [string[]] ToArray() { return $this.Items.ToArray() }
    [void] Dispose() { $this.Items.Clear(); $this.Disposed = $true }
}
$buffer = [Buffer]::new(@('one', 'two'))
try { $buffer.Add('three'); $buffer.ToArray() } finally { $buffer.Dispose() }

class Entity {
    [int] $Id
    Entity([int] $id) { $this.Id = $id }
    [string] ToString() { return "Entity $($this.Id)" }
}
class NamedEntity : Entity, System.IComparable {
    [string] $Name
    NamedEntity([int] $id, [string] $name) : base($id) { $this.Name = $name }
    [int] CompareTo([object] $other) { return $this.Id.CompareTo($other.Id) }
    [string] ToString() { return "$($this.Id): $($this.Name)" }
}
[NamedEntity]::new(1, 'first').ToString()

[Flags()]
enum Access : byte {
    None = 0
    Read = 1
    Write = 2
    Execute = 4
    All = 7
}
function Test-Access {
    param([Access] $Requested, [Access] $Granted)
    return ($Granted -band $Requested) -eq $Requested
}
Test-Access -Requested ([Access]::Read -bor [Access]::Write) -Granted ([Access]::All)

class Settings {
    [ValidateNotNullOrEmpty()][string] $Name = 'default'
    [ValidateRange(1, 65535)][int] $Port = 443
    static [string] $DefaultHost = 'localhost'
    Settings() {}
    Settings([string] $name, [int] $port) { $this.Name = $name; $this.Port = $port }
    static [Settings] Load([hashtable] $values) {
        return [Settings]::new($values.Name, $values.Port)
    }
    [uri] GetUri() {
        return [uri]::new("https://$([Settings]::DefaultHost):$($this.Port)/$($this.Name)")
    }
}
[Settings]::Load(@{ Name = 'example'; Port = 8443 }).GetUri()

$pattern = @'
^(?<name>[^:]+):(?<value>.*)$
'@
$inputText = @"
name:$env:USER
count:$(1 + 2)
"@
foreach ($line in ($inputText -split "`r?`n")) {
    if ($line -match $pattern.Trim()) {
        [pscustomobject]@{ Name = $Matches.name; Value = $Matches['value'] }
    }
}

param([string] $Path)
$stream = $null
try {
    $stream = [IO.File]::OpenRead($Path)
    $reader = [IO.StreamReader]::new($stream)
    try { $reader.ReadToEnd() } finally { $reader.Dispose() }
} catch [IO.FileNotFoundException], [IO.DirectoryNotFoundException] {
    Write-Warning "Missing file: $Path"
} catch [UnauthorizedAccessException] {
    Write-Error "Access denied: $Path"
    throw
} finally {
    if ($null -ne $stream) { $stream.Dispose() }
}

param([string[]] $Lines)
$result = [ordered]@{}
:lines foreach ($line in $Lines) {
    switch -Regex -CaseSensitive ($line) {
        '^#' { continue lines }
        '^(?<key>[^=]+)=(?<value>.*)$' {
            $result[$Matches.key.Trim()] = $Matches.value.Trim()
            continue lines
        }
        default { throw "Invalid line: $line" }
    }
}
[pscustomobject] $result

$script:Cache = @{}
function Get-CachedValue {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string] $Name, [switch] $Refresh)
    if ($Refresh -or -not $script:Cache.ContainsKey($Name)) {
        $script:Cache[$Name] = [pscustomobject]@{ Name = $Name; Created = [datetime]::UtcNow }
    }
    $script:Cache[$Name]
}
New-Alias -Name gcv -Value Get-CachedValue
Export-ModuleMember -Function Get-CachedValue -Alias gcv

